class Solution {
  private double[][] choose = new double[49][49];

  public double getProbability(int[] balls) {
    for (int i = 0; i < 49; i++) {
      choose[i][0] = 1;
      for (int j = 1; j <= i; j++)
        choose[i][j] = choose[i - 1][j - 1] + (j <= i - 1 ? choose[i - 1][j] : 0);
    }
    int total = 0;
    for (int b : balls) total += b;
    return dfs(balls, 0, 0, 0, 0, total / 2) / choose[total][total / 2];
  }

  // number of ways to hand the balls out so both boxes get the same count and the same number of
  // colours
  private double dfs(int[] balls, int color, int left, int leftKinds, int rightKinds, int half) {
    if (color == balls.length) {
      return left == half && leftKinds == rightKinds ? 1 : 0;
    }
    double ways = 0;
    int n = balls[color];
    for (int take = 0; take <= n; take++) {
      if (left + take > half) break;
      ways +=
          choose[n][take]
              * dfs(
                  balls,
                  color + 1,
                  left + take,
                  leftKinds + (take > 0 ? 1 : 0),
                  rightKinds + (take < n ? 1 : 0),
                  half);
    }
    return ways;
  }
}
